(function(w){"use strict";const host=w.BoundlessModules;if(!host?.registry||!host?.contracts||!host?.defineDomain)throw new Error("Boundless modular core failed to load");const expected=host.contracts.domains;const missing=expected.filter(id=>id!=="spirit-beasts"&&!host.domains?.[id]);if(missing.length)throw new Error("Missing Boundless domains: "+missing.join(", "));const report={version:"1.0.0",registered:host.registry.list().map(x=>x.id),domains:Object.keys(host.domains||{}),legacyRuntime:"active",migration:"not-started"};host.architecture=Object.freeze({report:()=>({...report,registered:host.registry.list().map(x=>x.id),domains:Object.keys(host.domains||{})})});w.dispatchEvent(new CustomEvent("boundless:modules-registered",{detail:report}));})(window);